CREATE TABLE IF NOT EXISTS "fa_admin" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "username" varchar(20) DEFAULT '',
  "nickname" varchar(50) DEFAULT '',
  "password" varchar(32) DEFAULT '',
  "salt" varchar(30) DEFAULT '',
  "avatar" varchar(255) DEFAULT '',
  "email" varchar(100) DEFAULT '',
  "mobile" varchar(11) DEFAULT '',
  "loginfailure" smallint NOT NULL DEFAULT '0',
  "logintime" bigint DEFAULT NULL,
  "loginip" varchar(50) DEFAULT NULL,
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  "token" varchar(59) DEFAULT '',
  "status" varchar(30) NOT NULL DEFAULT 'normal',
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_admin_username" UNIQUE ("username")
);


INSERT INTO "fa_admin" VALUES (1, 'admin', 'Admin', '', '', '/assets/img/avatar.png', 'admin@example.com', '', 0, 1491635035, '127.0.0.1',1491635035, 1491635035, '', 'normal') ON CONFLICT DO NOTHING;

CREATE TABLE IF NOT EXISTS "fa_admin_log" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "admin_id" int NOT NULL DEFAULT '0',
  "username" varchar(30) DEFAULT '',
  "url" varchar(1500) DEFAULT '',
  "title" varchar(100) DEFAULT '',
  "content" text NOT NULL,
  "ip" varchar(50) DEFAULT '',
  "useragent" varchar(255) DEFAULT '',
  "createtime" bigint DEFAULT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_admin_log_name" ON "fa_admin_log" ("username");

CREATE TABLE IF NOT EXISTS "fa_area" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "pid" int DEFAULT NULL,
  "shortname" varchar(100) DEFAULT NULL,
  "name" varchar(100) DEFAULT NULL,
  "mergename" varchar(255) DEFAULT NULL,
  "level" smallint DEFAULT NULL,
  "pinyin" varchar(100) DEFAULT NULL,
  "code" varchar(100) DEFAULT NULL,
  "zip" varchar(100) DEFAULT NULL,
  "first" varchar(50) DEFAULT NULL,
  "lng" varchar(100) DEFAULT NULL,
  "lat" varchar(100) DEFAULT NULL,
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_area_pid" ON "fa_area" ("pid");

CREATE TABLE IF NOT EXISTS "fa_attachment" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "category" varchar(50) DEFAULT '',
  "admin_id" int NOT NULL DEFAULT '0',
  "user_id" int NOT NULL DEFAULT '0',
  "url" varchar(255) DEFAULT '',
  "imagewidth" int DEFAULT 0,
  "imageheight" int DEFAULT 0,
  "imagetype" varchar(30) DEFAULT '',
  "imageframes" int NOT NULL DEFAULT '0',
  "filename" varchar(100) DEFAULT '',
  "filesize" int NOT NULL DEFAULT '0',
  "mimetype" varchar(100) DEFAULT '',
  "extparam" varchar(255) DEFAULT '',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  "uploadtime" bigint DEFAULT NULL,
  "storage" varchar(100) NOT NULL DEFAULT 'local',
  "sha1" varchar(40) DEFAULT '',
  PRIMARY KEY ("id")
);


