CREATE TABLE IF NOT EXISTS "fa_auth_rule" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "type" varchar(255) NOT NULL DEFAULT 'file',
  "pid" int NOT NULL DEFAULT '0',
  "name" varchar(100) DEFAULT '',
  "title" varchar(50) DEFAULT '',
  "icon" varchar(50) DEFAULT '',
  "url" varchar(255) DEFAULT '',
  "condition" varchar(255) DEFAULT '',
  "remark" varchar(255) DEFAULT '',
  "ismenu" smallint NOT NULL DEFAULT '0',
  "menutype" varchar(255) DEFAULT NULL,
  "extend" varchar(255) DEFAULT '',
  "py" varchar(30) DEFAULT '',
  "pinyin" varchar(100) DEFAULT '',
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  "weigh" int NOT NULL DEFAULT '0',
  "status" varchar(30) DEFAULT '',
  PRIMARY KEY ("id"),
  CONSTRAINT "fa_auth_rule_name" UNIQUE ("name")
);
CREATE INDEX IF NOT EXISTS "fa_auth_rule_pid" ON "fa_auth_rule" ("pid");
CREATE INDEX IF NOT EXISTS "fa_auth_rule_weigh" ON "fa_auth_rule" ("weigh");

