CREATE TABLE IF NOT EXISTS "fa_ems" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "event" varchar(30) DEFAULT '',
  "email" varchar(100) DEFAULT '',
  "code" varchar(10) DEFAULT '',
  "times" int NOT NULL DEFAULT 0,
  "ip" varchar(30) DEFAULT '',
  "createtime" bigint DEFAULT NULL,
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_sms" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "event" varchar(30) DEFAULT '',
  "mobile" varchar(20) DEFAULT '',
  "code" varchar(10) DEFAULT '',
  "times" int NOT NULL DEFAULT '0',
  "ip" varchar(30) DEFAULT '',
  "createtime" bigint DEFAULT '0',
  PRIMARY KEY ("id")
);


CREATE TABLE IF NOT EXISTS "fa_test" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id" int DEFAULT '0',
  "admin_id" int DEFAULT '0',
  "category_id" int DEFAULT '0',
  "category_ids" varchar(100),
  "tags" varchar(255) DEFAULT '',
  "week" varchar(255),
  "flag" varchar(255) DEFAULT '',
  "genderdata" varchar(255) DEFAULT 'male',
  "hobbydata" varchar(255),
  "title" varchar(100) DEFAULT '',
  "content" text,
  "image" varchar(100) DEFAULT '',
  "images" varchar(1500) DEFAULT '',
  "attachfile" varchar(100) DEFAULT '',
  "keywords" varchar(255) DEFAULT '',
  "description" varchar(255) DEFAULT '',
  "city" varchar(100) DEFAULT '',
  "array" varchar(255) DEFAULT '',
  "json" varchar(255) DEFAULT '',
  "multiplejson" varchar(1500) DEFAULT '',
  "price" numeric(10,2) DEFAULT '0.00',
  "views" int DEFAULT '0',
  "workrange" varchar(100) DEFAULT '',
  "startdate" date DEFAULT NULL,
  "activitytime" timestamp DEFAULT NULL,
  "year" integer DEFAULT NULL,
  "times" time DEFAULT NULL,
  "refreshtime" bigint DEFAULT NULL,
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  "deletetime" bigint DEFAULT NULL,
  "weigh" int DEFAULT '0',
  "switch" smallint DEFAULT '0',
  "status" varchar(255) DEFAULT 'normal',
  "state" varchar(255) DEFAULT '1',
  PRIMARY KEY ("id")
);


