CREATE TABLE IF NOT EXISTS "fa_user" (
  "id" int GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "group_id" int NOT NULL DEFAULT '0',
  "username" varchar(32) DEFAULT '',
  "nickname" varchar(50) DEFAULT '',
  "password" varchar(32) DEFAULT '',
  "salt" varchar(30) DEFAULT '',
  "email" varchar(100) DEFAULT '',
  "mobile" varchar(11) DEFAULT '',
  "avatar" varchar(255) DEFAULT '',
  "level" smallint NOT NULL DEFAULT '0',
  "gender" smallint NOT NULL DEFAULT '0',
  "birthday" date DEFAULT NULL,
  "bio" varchar(100) DEFAULT '',
  "money" numeric(10,2) NOT NULL DEFAULT '0.00',
  "score" int NOT NULL DEFAULT '0',
  "successions" int NOT NULL DEFAULT '1',
  "maxsuccessions" int NOT NULL DEFAULT '1',
  "prevtime" bigint DEFAULT NULL,
  "logintime" bigint DEFAULT NULL,
  "loginip" varchar(50) DEFAULT '',
  "loginfailure" smallint NOT NULL DEFAULT '0',
  "loginfailuretime" bigint DEFAULT NULL,
  "joinip" varchar(50) DEFAULT '',
  "jointime" bigint DEFAULT NULL,
  "createtime" bigint DEFAULT NULL,
  "updatetime" bigint DEFAULT NULL,
  "token" varchar(50) DEFAULT '',
  "status" varchar(30) DEFAULT '',
  "verification" varchar(255) DEFAULT '',
  PRIMARY KEY ("id")
);
CREATE INDEX IF NOT EXISTS "fa_user_username" ON "fa_user" ("username");
CREATE INDEX IF NOT EXISTS "fa_user_email" ON "fa_user" ("email");
CREATE INDEX IF NOT EXISTS "fa_user_mobile" ON "fa_user" ("mobile");

